DO $migration$ DECLARE definition text; signature text; BEGIN FOREACH signature IN ARRAY ARRAY['public.pm_quote_calendar_allocations(uuid,date)','public.pm_quote_calendar_stages(uuid,date)','public.pm_quote_stage_billing_fee(uuid)','public.pm_quote_conversion_totals(uuid)','public.pm_quote_preview_payment_date(uuid,date,uuid,jsonb,boolean)'] LOOP SELECT pg_get_functiondef(signature::regprocedure) INTO definition; definition:=replace(definition,'AS $function$','AS $function$'||chr(10)||'#variable_conflict use_column'); EXECUTE definition; END LOOP; END $migration$;